import{_ as e,a as s,o as i,a4 as a}from"./chunks/framework.-FZumj2l.js";const m=JSON.parse('{"title":"Wishlist","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/shop/wishlist/index.md","filePath":"api/rest-api/shop/wishlist/index.md","lastUpdated":1784902076000}'),o={name:"api/rest-api/shop/wishlist/index.md"};function h(r,t,d,l,n,p){return i(),s("div",null,t[0]||(t[0]=[a('<h1 id="wishlist" tabindex="-1">Wishlist <a class="header-anchor" href="#wishlist" aria-label="Permalink to &quot;Wishlist&quot;">​</a></h1><p>The Wishlist menu lets a logged-in customer save products to come back to later. A customer can list their wishlist, add or toggle a product, remove a single item, clear the whole list, or move a saved item straight into the cart.</p><h2 id="when-a-client-uses-this" tabindex="-1">When a client uses this <a class="header-anchor" href="#when-a-client-uses-this" aria-label="Permalink to &quot;When a client uses this&quot;">​</a></h2><p>The wishlist is per-customer and scoped to the current channel. Use <strong>toggle</strong> as a one-tap &quot;heart&quot; button — it adds the product if it isn&#39;t saved and removes it if it is. <strong>Move to cart</strong> transfers a saved item into the active cart so the customer can check out.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/wishlist/list.html">Get Wishlist Items</a></td><td><code>GET /api/shop/wishlists</code></td><td>List the customer&#39;s wishlist items.</td></tr><tr><td><a href="/api/rest-api/shop/wishlist/create.html">Create Wishlist Item</a></td><td><code>POST /api/shop/wishlists</code></td><td>Add a product to the wishlist.</td></tr><tr><td><a href="/api/rest-api/shop/wishlist/toggle.html">Toggle Wishlist Item</a></td><td><code>POST /api/shop/wishlists/toggle</code></td><td>Add the product if absent, remove it if present.</td></tr><tr><td><a href="/api/rest-api/shop/wishlist/delete.html">Delete Wishlist Item</a></td><td><code>DELETE /api/shop/wishlists/{id}</code></td><td>Remove one item.</td></tr><tr><td><a href="/api/rest-api/shop/wishlist/delete-all.html">Delete All Wishlist Items</a></td><td><code>POST /api/shop/delete-all-wishlists</code></td><td>Clear the whole wishlist.</td></tr><tr><td><a href="/api/rest-api/shop/wishlist/move-to-cart.html">Move Wishlist Item to Cart</a></td><td><code>POST /api/shop/move-wishlist-to-carts</code></td><td>Move a saved item into the cart.</td></tr></tbody></table><p>All Wishlist endpoints require the storefront key and a customer Bearer token — see <a href="/api/rest-api/authentication.html">Authentication</a>.</p>',7)]))}const u=e(o,[["render",h]]);export{m as __pageData,u as default};
